/// <summary>
/// The slots whose default is "nothing" (-1, the invalid handle) rather than
/// zero, by name: what a fake root's unserved slot answers for them too.
/// </summary>
internal static class ShimAreaNothingSlots
{
    public static bool Contains(string slot) => slot is "BeamEntityAt" or "CreateEntity" or "EntityGetIndex" or "EntityGetParent" or "FindConVarFlags" or "FindEntityByClassname" or "FxHandleEntityIndex" or "GetCommandClientHandle" or "GetPlayerHandle" or "MapSpawnCreate" or "RegisterConCommand" or "RegisterConVar";
}

